file.content:
@use "../abstract" as *;

.no-subpage-starfield {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;

  canvas {
    display: block;
    width: 100%;
    height: 100%;
    opacity: 0.96;
  }

  ~ * {
    position: relative;
    z-index: 1;
  }
}

html[data-contact-dom-state="pending"] {
  .main-content {
    opacity: 0;
    visibility: hidden;
    transform: translate3d(0, 24px, 0);
    pointer-events: none;
  }
}

html[data-contact-dom-state="ready"] {
  .main-content {
    opacity: 1;
    visibility: visible;
    transform: translate3d(0, 0, 0);
    transition:
      opacity var(--transition-slow),
      transform var(--transition-slow),
      visibility 0s linear 0s;
  }
}

html[data-contact-dom-state="leaving"],
html[data-contact-dom-state="success"] {
  .main-content {
    opacity: 1;
    visibility: visible;
    transform: translate3d(0, 0, 0);
  }
}

html[data-contact-dom-state],
body.is-contact {
  overflow: hidden;
}

body.is-contact {
  .scroll-container,
  #main,
  #main .main-content {
    min-height: 100vh;
    height: 100vh;
    overflow: hidden;
  }
}

#main.no-sub-about {
  .no-sub-about-contents {
    position: relative;
    z-index: var(--z-index-canvas-overlay);
    box-sizing: border-box;

    > section,
    > footer {
      position: relative;
      opacity: 1;

      [class$="__inner"] {
        width: 100%;
        pointer-events: auto;
      }
    }
  }

  .no-sub-about-journey-surface {
    --about-journey-surface-alpha: 0.24;
    background: rgba(0, 0, 0, var(--about-journey-surface-alpha));
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
  }

  .no-main-contact[data-scene="contact"] {
    .no-container-2xl {
      position: sticky;
      inset: auto;
      top: var(--header-height);
      min-height: calc(100vh - var(--header-height));
      justify-content: center;
      padding-top: var(--gutter-lg);
      padding-bottom: var(--gutter-lg);
    }

    @include mq(md) {
      .no-container-2xl {
        min-height: calc(100svh - var(--header-height));
      }
    }
  }
}

.no-sub-about {
  &-section {
    &__inner {
      width: 100%;
    }

    &__txt {
      display: flex;
      flex-direction: column;
      gap: fluid(24, 48);
    }
  }

  &-hero-intro {
    padding-top: var(--header-height);

    &__inner {
      height: calc(100vh - var(--header-height));
      padding-bottom: var(--gutter-xl);
    }

    &__txt {
      justify-content: space-between;
      height: 100%;
      padding-top: var(--gutter-2xl);
    }

    &__bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    &__title {
      display: flex;
      flex-direction: column;
      h2 {
        .line {
          text-align: right;
        }
      }
    }

    &__desc p {
      margin-top: var(--gutter-xs);
      max-width: fluid(360, 520);
    }

    &__info {
      display: flex;
      justify-content: flex-end;
    }
  }

  &-hero-slogan {
    --hero-slogan-surface-alpha: 0.24;

    width: 100%;
    position: relative;
    background: rgba(0, 0, 0, var(--hero-slogan-surface-alpha));
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
    &__title {
      text-align: center;

      h2 {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: fluid(8, 16);
        line-height: 0.9;
      }

      .line {
        text-align: center;
      }
    }

    &__line {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: fluid(10, 18);
      .weak {
        opacity: 0.4;
      }
    }

    &__keyword-shell {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: fluid(10, 14);
      color: var(--clr-white-100);
      white-space: nowrap;
    }

    &__bracket {
      color: color-mix(in srgb, var(--clr-white-100) 72%, transparent);
      font-weight: 400;
    }

    &__keyword-viewport {
      position: relative;
      display: inline-block;
      height: 0.98em;
      width: auto;
      flex: 0 0 auto;
      overflow: hidden;
      vertical-align: top;
      contain: paint;
    }

    &__keyword-track {
      display: flex;
      flex-direction: column;
      align-items: center;
      transform: translate3d(0, 0, 0);
      will-change: transform;
    }

    &__keyword {
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 0.98em;
      opacity: 0.4;
      text-shadow: 0 0 0 rgba(255, 255, 255, 0);
      will-change: opacity, text-shadow;
    }

    &__inner {
      min-height: var(--scene-shell-span);
      position: relative;
    }

    &__txt {
      position: sticky;
      top: var(--header-height);
      min-height: calc(100vh - var(--header-height));
      display: flex;
      align-items: center;
      justify-content: center;
      padding: var(--gutter-4xl) 0;
    }

    > div {
      height: 100%;
    }

    &__top {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: var(--gutter-sm);
      width: 100%;
    }

    &__contents {
      align-items: flex-start;
    }

    &__bottom {
      width: 100%;
      padding-top: var(--gutter-4xl);

      p + p {
        margin-top: var(--gutter-lg);
      }
    }

    @include mq(md) {
      &__title {
        h2 {
          gap: fluid(6, 10);
        }
      }

      &__line {
        gap: fluid(8, 12);
      }

      &__keyword-shell {
        gap: fluid(8, 10);
      }

      &__txt {
        min-height: calc(100vh - var(--header-height));
        padding: var(--gutter-2xl) 0;
      }
    }

    @include mq(sm) {
      &__keyword-shell {
        gap: fluid(6, 8);
      }
    }
  }

  &-who {
    padding: var(--gutter-4xl) 0;

    &__inner {
      align-items: start;
    }

    &__contents {
      min-height: var(--scene-shell-span);
    }

    &__stage {
      position: sticky;
      top: var(--header-height);
      min-height: calc(100vh - var(--header-height));
      display: flex;
      justify-content: center;
      align-items: center;
      padding: fluid(28, 40) 0;
      overflow: clip;
    }

    &__visual {
      position: relative;
      width: min(100%, 1080px);
      min-height: min(74vmin, 760px);
      display: flex;
      align-items: center;
      justify-content: center;
      isolation: isolate;
    }

    &__sr-title {
      @include blind();
    }

    &__ring {
      position: absolute;
      left: 50%;
      top: 50%;
      width: min(54vmin, 560px);
      aspect-ratio: 1;
      border-radius: 50%;
      border: 1px solid
        color-mix(in srgb, var(--clr-white-100) 12%, transparent);
      background: radial-gradient(
        circle,
        color-mix(in srgb, var(--clr-white-100) 8%, transparent) 0%,
        transparent 62%
      );
      transform: translate3d(-50%, -50%, 0) scale(0.72);
      opacity: 0;
      z-index: 1;
      pointer-events: none;
      will-change: transform, opacity;
    }

    &__title-layer {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      text-align: center;
      line-height: 0.86;
      letter-spacing: -0.05em;
      color: var(--clr-white-100);
      pointer-events: none;
      will-change: transform, opacity;
    }

    &__title-layer--back {
      z-index: 3;
    }

    &__title-layer--front {
      z-index: 10;
    }

    &__title-line {
      display: inline-flex;
      align-items: center;
      gap: fluid(18, 28);
    }

    &__title-line + &__title-line {
      margin-top: fluid(4, 10);
    }

    &__title-part {
      display: inline-block;
    }

    &__title-part--ghost {
      opacity: 0;
    }

    &__card-list {
      position: absolute;
      inset: 0;
      margin: 0;
      padding: 0;
      list-style: none;
      pointer-events: none;
    }

    &__card {
      --about-who-card-x: 0vmin;
      --about-who-card-y: 0vmin;
      --about-who-card-rotate: 0deg;
      --about-who-card-scale: 0.88;
      --about-who-card-opacity: 0;
      --about-who-card-z: 1;

      position: absolute;
      left: 50%;
      top: 50%;
      width: min(26vmin, 280px);
      display: flex;
      flex-direction: column;
      gap: fluid(10, 14);
      transform: translate3d(
          calc(-50% + var(--about-who-card-x)),
          calc(-50% + var(--about-who-card-y)),
          0
        )
        rotate(var(--about-who-card-rotate)) scale(var(--about-who-card-scale));
      transform-origin: center;
      opacity: var(--about-who-card-opacity);
      z-index: var(--about-who-card-z);
      will-change: transform, opacity;
    }

    &__card-media {
      position: relative;
      width: 100%;
      margin: 0;
      overflow: hidden;
      border: 1px solid
        color-mix(in srgb, var(--clr-white-100) 14%, transparent);
      background: color-mix(in srgb, var(--clr-black-100) 72%, transparent);
      box-shadow:
        0 20px 40px rgba(0, 0, 0, 0.32),
        0 0 0 1px rgba(255, 255, 255, 0.06);

      img {
        display: block;
        width: 100%;
        aspect-ratio: 4 / 5;
        object-fit: cover;
      }
    }

    @include mq(md) {
      &__stage {
        padding-top: fluid(20, 28);
        padding-bottom: fluid(20, 28);
      }

      &__visual {
        width: 100%;
      }

      &__title-line {
        gap: fluid(12, 18);
      }

      &__card {
        width: min(32vmin, 232px);
      }

      &__ring {
        width: min(66vmin, 420px);
      }
    }
  }

  &-mission-vision {
    padding: var(--gutter-4xl) 0;
    position: relative;
    background: rgba(0, 0, 0, var(--hero-slogan-surface-alpha));
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
    > div {
      height: 100%;
    }

    &__inner {
      height: 100%;
      @include flex-center();
      flex-direction: column;
    }
  }

  &-vision {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--gutter-md);
    width: 64%;
    margin-left: auto;

    &__headline {
      display: block;
    }
    &__description {
    }
  }

  &-mission {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--gutter-xl);
    z-index: 2;
    margin-top: var(--gutter-4xl);

    &__title {
      h2 {
        display: flex;
        align-items: center;
        gap: var(--gutter-sm);
      }
    }

    &__wrap {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: var(--gutter-md);
      align-items: stretch;
    }

    &__card {
      position: relative;
      --corner-panel-padding: fluid(24, 36);
      --corner-panel-border: var(--clr-border-weak);
      --corner-panel-border-hover: var(--clr-border-default);
      --corner-panel-background: transparent;
      --corner-panel-background-hover: color-mix(
        in srgb,
        var(--clr-border-weak) 12%,
        transparent
      );
      --corner-panel-corner: var(--clr-border-strong);
      --corner-panel-corner-hover: var(--clr-text-desc);
      --corner-panel-hover-offset-y: -4px;

      &--wrap {
        position: relative;
        z-index: 1;
        height: 100%;
        display: flex;
        flex-direction: column;
        gap: var(--gutter-sm);
        padding: var(--gutter-sm) var(--gutter-md);

        h3 {
          margin-top: 0;
          font-family: var(--family-en-title);
        }

        p {
          font-family: var(--family-ko-title);
          margin-top: 0;
        }
      }
    }
  }

  &-services {
    width: 100%;

    &__body {
      width: 100%;
      background: rgba(0, 0, 0, 0.24);
      backdrop-filter: blur(24px);
      -webkit-backdrop-filter: blur(24px);
    }

    &__txt {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-md);
    }

    &__list {
      display: flex;
      flex-direction: column;
    }

    &__item {
      display: grid;
      grid-template-columns: 2fr 6fr 4fr;
      gap: var(--gutter-sm);
      align-items: center;
      padding: var(--gutter-2xl) 0;
      border-top: 1px solid rgba(255, 255, 255, 0.12);

      &:last-child {
        border-bottom: 1px solid rgba(255, 255, 255, 0.12);
      }

      @include mq(md) {
        grid-template-columns: 1fr;
        gap: var(--gutter-xs);
      }
    }

    .no-services__num {
      color: rgba(255, 255, 255, 0.56);
      display: flex;
      align-items: center;
      min-height: fluid(16, 22);

      .no-loop-filter-rect {
        gap: 0;

        span {
          width: fluid(4, 6);
          height: fluid(4, 6);
        }
      }
    }
  }

  &-awards {
    padding: var(--gutter-4xl) 0;
    &__title {
      text-align: center;
      .line {
        text-align: center;
      }
    }
    &__contents {
      margin-top: var(--gutter-2xl);
      height: 100%;
    }
  }

  &-client {
    padding: var(--gutter-4xl) 0;
    > div {
      height: 100%;
    }
    &__inner {
      height: 100%;
    }

    &__contents {
      @include flex-center();
      flex-direction: column;
      height: 100%;
    }
    &__list {
      position: relative;
      margin-top: var(--gutter-2xl);
    }

    &__items {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: var(--gutter-md);
    }

    &__item {
      background: rgba(255, 255, 255, 0.04);
      padding: var(--gutter-md);
      backdrop-filter: blur(24px);
      -webkit-backdrop-filter: blur(24px);

      a {
        display: block;
      }

      img {
        display: block;
      }
    }
  }

  &-footer {
    &__inner {
      padding-top: fluid(48, 72);
      padding-bottom: fluid(32, 48);
      border-top: 1px solid
        color-mix(in srgb, var(--clr-white-100) 14%, transparent);
    }

    &__meta,
    &__links {
      display: flex;
      flex-wrap: wrap;
      gap: var(--gutter-sm) var(--gutter-md);
      color: var(--clr-text-body);
    }

    &__links {
      color: var(--clr-text-title);
    }
  }
}

.no-gallery {
  &__list {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: var(--gutter-sm);
  }
  &__item {
  }
  &__img {
    @include img-auto-cover(62.5%);
    img {
      @include img-cover;
    }
  }
  &__content {
    &-head {
      display: flex;
      gap: var(--gutter-xs);
      justify-content: space-between;
      align-items: center;
    }
    &-title {
      h3 {
        @include line-clamp(2);
      }
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// .no-warp-bg — objects/Space.ts가 body에 직접 생성하는 전역 파티클 배경 캔버스.
// careers / inside 페이지에서만 존재. position:fixed로 페이지 전체 뒤에 고정.
// ─────────────────────────────────────────────────────────────────────────────
.no-warp-bg {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  pointer-events: none;
  z-index: var(--z-index-bg);
  opacity: 0.65;
}

.no-sub-visual {
  position: relative;
  width: 100%;
  @include flex-center();
  text-align: center;
  margin-top: var(--header-height);
  min-height: fluid(280, 320);

  &__desc {
    margin-top: var(--gutter-md);
  }
}

.no-sub-careers-view {
  margin-top: var(--header-height);
  padding: fluid(64, 128) 0;
  .no-corner-btn {
    @include flex-center();
  }
  &__inner {
    display: grid;
    grid-template-columns: 8fr 4fr;
    gap: var(--gutter-md);
    @include mq(md) {
      grid-template-columns: 1fr;
    }
  }
  &__wrap {
    display: flex;
    flex-direction: column;
  }
  &__title {
    padding-bottom: var(--gutter-sm);
    border-bottom: 1px solid var(--clr-border-default);
    margin-top: var(--gutter-md);
    h2 {
    }
  }

  &__map {
    iframe {
      width: 100%;
      border: 0;
      display: block;
      aspect-ratio: 16/9;
    }
  }
  &__content {
    margin-top: var(--gutter-md);
  }

  &__section {
    padding: var(--gutter-md) 0;
    border-bottom: 1px solid var(--clr-border-default);

    h3 {
      @include font("f-body-2");
      font-weight: 700;
      color: var(--clr-text-title);
      margin-bottom: fluid(12, 20);
      letter-spacing: 0.02em;
    }

    p {
      @include font("f-body-3");
      color: var(--clr-text-body);
      line-height: 1.8;

      & + p {
        margin-top: fluid(8, 12);
      }
    }

    ul {
      display: flex;
      flex-direction: column;
      gap: fluid(8, 12);
      padding-left: 0;
      list-style: none;

      li {
        @include font("f-body-3");
        color: var(--clr-text-body);
        line-height: 1.7;
        display: flex;
        align-items: flex-start;
        gap: fluid(8, 12);

        &::before {
          content: "";
          display: block;
          flex-shrink: 0;
          width: 4px;
          height: 4px;
          border-radius: 50%;
          background: var(--clr-primary-def);
          margin-top: 0.6em;
        }
      }
    }
  }

  &__info {
    display: flex;
    flex-direction: column;
    gap: var(--gutter-md);
    position: sticky;
    top: calc(var(--header-height) + var(--gutter-md));
    align-self: flex-start;
    @include mq(md) {
      position: static;
      border-top: 1px solid var(--clr-border-default);
      padding-top: var(--gutter-md);
      margin-top: 0;
    }
    &-card {
      border: 1px solid var(--clr-border-default);
      padding: var(--gutter-sm);
    }
    &-item {
      display: flex;
      align-items: center;
      gap: var(--gutter-xs);
      padding: var(--gutter-xs) 0;
      border-bottom: 1px solid var(--clr-border-default);
      span {
        color: var(--clr-text-body);
        opacity: 0.48;
        flex-shrink: 0;
        width: fluid(48, 64);
        @include font("f-body-4");
      }
      p {
        color: var(--clr-text-title);
        opacity: 1;
        @include font("f-body-3");
        font-weight: 600;
      }
    }
    &-list {
      display: flex;
      flex-direction: column;
      margin-bottom: fluid(16, 24);
    }
  }
}

.no-sub-careers {
  padding-bottom: fluid(64, 128);
  .no-sub-list {
    .no-meta-list {
      margin-top: fluid(16, 24);
    }
  }
