.no-award-hover-preview {
  position: fixed;
  top: 0;
  left: 0;
  @media (hover: none) {
    display: none;
  }
  width: fluid(220, 320);
  border: 1px solid var(--clr-border-default);
  background: var(--clr-surface-elevated);
  box-shadow: var(--shadow-floating-card);
  overflow: hidden;
  pointer-events: none;
  z-index: calc(var(--z-index-modal) + 1);
  opacity: 0;
  transform: translateY(14px) scale(0.97);
  clip-path: inset(0 0 100% 0);
  transition:
    opacity var(--duration-default) var(--ease-smooth),
    transform var(--duration-default) var(--ease-smooth),
    clip-path var(--duration-default) var(--ease-smooth);
  will-change: transform, clip-path, opacity;

  &.is-visible {
    opacity: 1;
    transform: translateY(0) scale(1);
    clip-path: inset(0 0 0 0);

    img {
      transform: scale(1);
      opacity: 1;
    }
  }

  &.is-closing {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
    clip-path: inset(100% 0 0 0);
  }

  img {
    @include img-cover;
    display: block;
    aspect-ratio: 16/10;
    transform: scale(1.08);
    opacity: 0.92;
    transition:
      transform calc(var(--duration-default) * 1.1) var(--ease-smooth),
      opacity var(--duration-default) var(--ease-smooth);
  }
}

.no-sub-award-video-preview {
  position: fixed;
  top: 0;
  right: fluid(24, 56);
  transform: translateY(-50%);
  width: fluid(280, 480);
  aspect-ratio: 16 / 9;
  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  clip-path: inset(50% 0 50% 0);
  transition:
    opacity 0.4s cubic-bezier(0.76, 0, 0.24, 1),
    visibility 0.4s cubic-bezier(0.76, 0, 0.24, 1),
    clip-path 0.48s cubic-bezier(0.76, 0, 0.24, 1),
    top 0.44s cubic-bezier(0.76, 0, 0.24, 1);
  z-index: 100;

  &.is-visible {
    opacity: 1;
    visibility: visible;
    clip-path: inset(0% 0 0% 0);
  }

  &.is-visible.is-switching {
    clip-path: inset(50% 0 50% 0);
  }

  &.is-closing {
    opacity: 0;
    clip-path: inset(50% 0 50% 0);
  }

  video {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }

  @include mq(md) {
    display: none;
  }
}

.no-sub-contact {
  position: relative;
  z-index: var(--z-index-canvas-overlay);
  margin-top: var(--header-height);
  height: calc(100vh - var(--header-height));
  height: calc(100dvh - var(--header-height));
  display: flex;
  flex-direction: column;

  .no-container-xl {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;

    > form {
