&-proof {
  width: 100%;

  &__body {
    width: 100%;
    background: rgba(0, 0, 0, 0.24);
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
  }

  &__txt {
    display: flex;
    flex-direction: column;
    gap: var(--gutter-md);
    margin-bottom: var(--gutter-2xl);

    p {
      max-width: fluid(480, 640);
      color: var(--clr-text-body);
    }
  }

  &__grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: var(--gutter-md);
    perspective: 1200px;
    perspective-origin: 50% 30%;

    > .is-block-reveal-up {
      opacity: 0;
      transform: translateZ(-80px) scale(0.88);
      transition:
        opacity 0.64s cubic-bezier(0.22, 1, 0.36, 1),
        transform 0.72s cubic-bezier(0.22, 1, 0.36, 1);
      transition-delay: var(--proof-card-delay, 0s);

      &.is-visible {
        opacity: 1;
        transform: translateZ(0) scale(1);
      }
    }

    @include mq(lg) {
      grid-template-columns: repeat(2, 1fr);
    }

    @include mq(sm) {
      grid-template-columns: 1fr;
    }
  }

  &__card {
    position: relative;
    --corner-panel-padding: fluid(20, 32);
    --corner-panel-border: var(--clr-border-weak);
    --corner-panel-border-hover: var(--clr-border-default);
    --corner-panel-background: transparent;
    --corner-panel-background-hover: color-mix(
      in srgb,
      var(--clr-border-weak) 12%,
      transparent
    );
